ProcessingScript.script:
import java.util.Properties;
import java.io.InputStream;
import com.boomi.execution.ExecutionUtil;

logger = ExecutionUtil.getBaseLogger();

for( int i = 0; i < dataContext.getDataCount(); i++ ) {
    InputStream is = dataContext.getStream(i);
    Properties props = dataContext.getProperties(i);

    def accountPrefix = props.getProperty("document.dynamic.userdefined.DDP-ACCOUNT_NAME_PREFIX");
    def lastAccount = props.getProperty("document.dynamic.userdefined.DDP-LAST_ACCOUNT_LIKE_PREFIX");
    logger.info("LastAccount: " + lastAccount)
    def m = lastAccount =~ /^[a-zA-Z0-9]+(\d{4,4})$/
    def seq = '0001'
    def newAccountNumber = ''

    if(m.find()) {
        seq = Integer.parseInt(m.findAll().first()[1])
        logger.info(m.findAll().first().toString())
        logger.info(seq.toString())
        seq++
        seq = seq.toString().padLeft(4, '0')
    }

    props.setProperty("document.dynamic.userdefined.DDP-NEW_CUSTNMBR", accountPrefix + seq);
    logger.info("New CUSTNMBR: " + accountPrefix + seq);
    dataContext.storeStream(is, props);
}
